class H{int C;int[]v;String s(boolean p,String[]L){C=L[0].length();int N=L.length*C,n=0,a=N,b,q;v=new int[N];for(;a-->0;)if((q=L[a/C].charAt(a%C))>46)for(b=a;b-->0;)if(L[b/C].charAt(b%C)==q){int x=b/C-a/C,y=b%C-a%C;if(p){g(2*a-b,a%C-y);g(2*b-a,b%C+y);}else for(int c=N;c-->0;)if((c/C-a/C)*y==(c%C-a%C)*x)v[c]=1;}for(var z:v)n+=z;return n+"";}void g(int b,int c){if((b|c)>=0&b<v.length&c<C)v[b]=1;}}
